const markerClickEvent=new Event('markerClick');class Circuit{#currentMarkerIndex=null;#bounds=new google.maps.LatLngBounds();constructor(lat_id,lng_id,map_id,input_id,icon,type='step'){this.lat_id=lat_id;this.lng_id=lng_id;this.map_id=map_id;this.input_id=input_id;this.type=type;this.lat=6.366667;this.lng=2.433333;this.icon=icon;this.markers=[];this.map_options={center:new google.maps.LatLng(this.lat,this.lng),zoom:13,mapTypeId:google.maps.MapTypeId.ROADMAP,panControl:!0,panControlOptions:{position:google.maps.ControlPosition.TOP_RIGHT},zoomControl:!0,zoomControlOptions:{style:google.maps.ZoomControlStyle.LARGE,position:google.maps.ControlPosition.TOP_left}};this.map=new google.maps.Map(document.getElementById(this.map_id),this.map_options);this.infowindows=[];this.input=document.getElementById(this.input_id);this.autocomplete=this.setAutocomplete();let self=this;google.maps.event.addListener(this.map,'click',function(event){if(self.markers.length>0&&self.#currentMarkerIndex!=null){$('#'+self.lat_id).val(event.latLng.lat());$('#'+self.lng_id).val(event.latLng.lng());$.each(self.infowindows,function(index,infowindow){infowindow.close()});var geocoder=new google.maps.Geocoder();geocoder.geocode({"latLng":event.latLng},function(results,status){if(status==google.maps.GeocoderStatus.OK){var lat=results[0].geometry.location.lat(),lng=results[0].geometry.location.lng(),placeName=results[0].address_components[0].long_name,latlng=new google.maps.LatLng(lat,lng);self.moveMarker(placeName,latlng);$("#"+self.input_id).val(results[0].formatted_address)}})}else{$.notify({message:"Aucun marqueur n'a été ajouté"},{type:"danger",timer:1000,placement:{from:'top',align:'right'}})}})}
setAutocomplete(){let self=this;let autocomplete=new google.maps.places.Autocomplete(this.input,{types:["establishment","geocode"]});autocomplete.bindTo('bounds',this.map);google.maps.event.addListener(autocomplete,'place_changed',function(event){self.infowindows[self.#currentMarkerIndex].close();var place=autocomplete.getPlace();if(place.geometry.viewport){self.map.fitBounds(place.geometry.viewport)}else{self.map.setCenter(place.geometry.location);self.map.setZoom(17)}
self.moveMarker(place.name,place.geometry.location);$('#'+self.lat_id).val(place.geometry.location.lat());$('#'+self.lng_id).val(place.geometry.location.lng())});return autocomplete}
moveMarker(title,latlng){this.markers[this.#currentMarkerIndex].setPosition(latlng);if(this.infowindows[this.#currentMarkerIndex].getContent()){this.infowindows[this.#currentMarkerIndex].open(this.map,this.markers[this.#currentMarkerIndex])}}
addMarker(lat,lng,title,content){let map=this.map;let icon=this.icon;let infowindow=new google.maps.InfoWindow();var marker=new google.maps.Marker({position:new google.maps.LatLng(lat,lng),map:map,title:title,icon:icon,animation:google.maps.Animation.DROP,});$('#'+this.lat_id).val(lat);$('#'+this.lng_id).val(lng);this.#currentMarkerIndex=this.markers.length;this.#bounds.extend(marker.position);if(this.type==='step'){marker.setLabel({text:String(this.markers.length+1),color:'#fff',})}
if(content){infowindow.setContent(content);infowindow.open(map,marker)}
this.markers.push(marker);this.infowindows.push(infowindow);let self=this;google.maps.event.addListener(marker,'click',function(){var latLng=marker.getPosition();var lat=latLng.lat();var lng=latLng.lng();$('#'+self.lat_id).val(lat);$('#'+self.lng_id).val(lng);$.each(self.markers,function(index,marker){if(marker.getPosition().lat()==lat&&marker.getPosition().lng()==lng){if(self.infowindows[index].getContent()){self.infowindows[index].open(self.map,marker)}
self.#currentMarkerIndex=index;dispatchEvent(markerClickEvent)}})})
$('#'+self.lat_id).val('');$('#'+self.lng_id).val('');return marker}
removeMarker(marker){self=this;marker.setMap(null);this.markers.splice(this.markers.indexOf(marker),1);this.infowindows.splice(this.markers.indexOf(marker),1);this.markers.forEach(function(marker,index){let label=self.type==='step'?String(index+1):'';marker.setLabel({text:label,color:'#fff'})})}
removeMarkers(){$.each(this.markers,function(index,marker){marker.setMap(null)});this.markers=[];this.infowindows=[]}
centerMap(marker){this.map.panTo(marker.getPosition())}
centerMapOnLocation(location){this.map.panTo(location)}
updateMarker(marker,lat,lng,title,content){var lat=marker.position.lat();var lng=marker.position.lng();marker.setPosition(new google.maps.LatLng(lat,lng));marker.setTitle(title);let self=this;$.each(this.markers,function(index,marker){if(marker.getPosition().lat()==lat&&marker.getPosition().lng()==lng){self.infowindows[index].setContent(content)}});this.#currentMarkerIndex=null}
getCurrentMarkerIndex(){return this.#currentMarkerIndex}
initCurrentMarkerIndex(){this.#currentMarkerIndex=null}}